param([string]$HeraCli = "hera-godot"); $ErrorActionPreference = "Stop"; Push-Location $PSScriptRoot; try { if ((& $HeraCli --version) -notmatch '^(hera-godot )?v?2\.0\.0$') { throw "Pass -HeraCli pointing to released hera-godot 2.0.0 from npm/Scoop." }; New-Item -ItemType Directory -Force addons | Out-Null; Copy-Item ../../addons/hera_agent_godot addons -Recurse -Force; dotnet build; if ($LASTEXITCODE) { throw "dotnet build failed" }; & $HeraCli csharp-host install; if ($LASTEXITCODE) { throw "compiler helper install failed" } } finally { Pop-Location }
